'use client';
import { createParts } from '@ui-sdk/react/primitive';
import type { ComponentProps } from 'react';
import { rating } from '@/components/ui/sdk/rating/primitive';
import { definedProps, type UIProps } from '@/registry/base-nova/protoform/lib/sdk-props';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

function stateClassName<State>(
  classes: string,
  className: string | ((state: State) => string | undefined) | undefined
) {
  return (state: State) => cn(classes, typeof className === 'function' ? className(state) : className);
}

const parts = createParts(rating, { root: 'div', star: 'button' });
export function Rating({ className, ...props }: UIProps<ComponentProps<typeof parts.Root>>) {
  return <parts.Root {...definedProps(props)} className={stateClassName('inline-flex gap-1', className)} />;
}
export function RatingStar({ className, ...props }: UIProps<ComponentProps<typeof parts.Star>>) {
  return (
    <parts.Star
      {...definedProps(props)}
      className={stateClassName(
        'flex size-9 items-center justify-center rounded-md border border-input text-muted-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring data-filled:bg-primary data-filled:text-primary-foreground',
        className
      )}
    />
  );
}

import {
  announce,
  type ChangeDetails,
  createChange,
  createRovingFocus,
  definePrimitive,
  type PropSchema,
} from '@ui-sdk/core';

export interface RatingOptions {
  defaultValue?: number;
  onValueChange?: (value: number, details: ChangeDetails<'item-press' | 'list-navigation' | 'imperative'>) => void;
  value?: number;
}

function checkedRating(value: number) {
  if (!Number.isInteger(value) || value < 0 || value > 5) {
    throw new RangeError('Rating must be an integer from 0 to 5.');
  }
  return value;
}

const optionSchema = {
  value: 'number',
  defaultValue: 'number',
  onValueChange: 'callback',
} satisfies PropSchema<RatingOptions>;

const definition = definePrimitive({
  name: 'protoform-rating',
  options: optionSchema,
  controlled: ['value'],
  state: (options: RatingOptions): { value: number; focused: string | null } => ({
    value: checkedRating(options.value ?? options.defaultValue ?? 0),
    focused: null,
  }),
  sync: (options) => (options.value === undefined ? {} : { value: checkedRating(options.value) }),
  api: (context) => {
    const change = createChange(context);
    const roving = createRovingFocus(context, {
      slot: 'star',
      key: 'focused',
      remember: false,
      preferred: (star) => Number(star.key) === context.store.get().value,
      claims: (state, star) => (state.value === 0 ? star.key === '1' : Number(star.key) === state.value),
      orientation: () => 'both',
      loop: () => true,
    });
    const setRating = (value: number, reason: 'item-press' | 'list-navigation' | 'imperative', event?: Event) => {
      change('value', checkedRating(value), { reason, ...(event === undefined ? {} : { event }) });
      if (context.store.get().value === value) {
        announce(value === 0 ? 'Rating cleared' : `${value} of 5 stars`);
      }
    };
    return {
      roving,
      setValue: (value: number) => setRating(value, 'imperative'),
      pick: (value: number, event?: Event) => setRating(value, 'item-press', event),
      keydown(event: KeyboardEvent, el: HTMLElement) {
        const moved = roving.keydown(event, el);
        if (moved) {
          setRating(Number(moved.key), 'list-navigation', event);
        }
      },
    };
  },
  slots: (slot) => ({
    root: slot({ role: 'radiogroup', keys: { none: 'The star parts handle radio-group navigation.' } }),
    star: slot<{ value: string }>({
      props: { value: 'string' },
      role: 'radio',
      focus: 'roving',
      keys: ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'],
      attrs: (state, part) => ({
        type: 'button',
        'aria-checked': String(Number(part.key) === state.value),
        tabindex: part.api.roving.tabIndex(state, part),
        'data-filled': Number(part.key) <= state.value ? '' : undefined,
      }),
      press: ({ api, key }, event) => api.pick(Number(key), event),
      on: {
        keydown: (event, { el, api }) => {
          if (el) {
            api.keydown(event, el);
          }
        },
      },
      bind: (el, part) => part.api.roving.bind(el, part),
    }),
  }),
  agent: { actions: ['setValue'] },
});

export const rating = Object.assign(definition, { options: optionSchema });

'use client';

import { type AsyncOptionsContext, useAsyncOptions } from '@ui-sdk/react/async-options';
import { useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Combobox, type ComboboxOption, type ComboboxProps } from '@/components/ui/combobox';
import { definedProps } from '@/registry/base-nova/protoform/lib/sdk-props';

export interface AsyncOptionComboboxProps extends Omit<ComboboxProps, 'options' | 'loading' | 'filter' | 'footer'> {
  debounce?: number;
  immediate?: boolean;
  load: (
    query: string,
    context: AsyncOptionsContext
  ) => Promise<ComboboxOption[] | { items: ComboboxOption[]; hasMore?: boolean }>;
}
export function AsyncOptionCombobox({
  load,
  debounce,
  immediate,
  onInputValueChange,
  ...props
}: AsyncOptionComboboxProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const options = useAsyncOptions(load, definedProps({ debounce, immediate }));
  function focusSearch() {
    containerRef.current?.querySelector<HTMLElement>('[role="combobox"]')?.focus();
  }
  return (
    <div className="space-y-2" ref={containerRef}>
      <Combobox
        {...props}
        filter={false}
        footer={
          <>
            {options.status === 'error' ? (
              <div className="space-y-2 p-2">
                <p role="alert">Could not load options.</p>
                <Button
                  onClick={() => {
                    focusSearch();
                    options.reload();
                  }}
                  type="button"
                  variant="outline"
                >
                  Retry options
                </Button>
              </div>
            ) : null}
            {options.hasMore && options.status === 'idle' ? (
              <div className="p-2">
                <Button
                  onClick={() => {
                    focusSearch();
                    options.loadMore();
                  }}
                  type="button"
                  variant="outline"
                >
                  Load more options
                </Button>
              </div>
            ) : null}
          </>
        }
        loading={options.status === 'loading'}
        onInputValueChange={(query) => {
          if (query !== options.query) {
            options.setQuery(query);
          }
          onInputValueChange?.(query);
        }}
        options={options.items}
      />
    </div>
  );
}

'use client';

import type { Preference } from '@ui-sdk/core';
import { usePreference } from '@ui-sdk/react/preferences';
import type { ComponentProps } from 'react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { definedProps } from '@/registry/base-nova/protoform/lib/sdk-props';

export type { Preference, PreferenceOptions } from '@ui-sdk/core';
export { createLocalStorage, createPreference } from '@ui-sdk/core';
export { Preferences } from '@ui-sdk/react/preferences';
export function PreferenceSelect<Value extends string>({
  preference,
  label,
  ...props
}: {
  preference: Preference<Value>;
  label: string;
  'data-agent-confirm'?: string;
  'data-agent-hidden'?: boolean;
  'data-agent-secret'?: boolean;
} & Omit<ComponentProps<typeof SelectTrigger>, 'children' | 'aria-label'>) {
  const state = usePreference(preference);
  return (
    <Select
      items={preference.values.map((value) => ({ label: value, value }))}
      onValueChange={(value, details) => {
        if (value !== null) {
          const accepted = preference.set(
            value,
            definedProps({
              event: details.event,
              reason: 'item-press' as const,
            })
          );
          if (!accepted && preference.get().value !== value) {
            details.cancel();
          }
        }
      }}
      value={state.value}
    >
      <SelectTrigger {...props} aria-label={label}>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {preference.values.map((value) => (
          <SelectItem key={value} value={value}>
            {value}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

export type UIProps<T> = { [K in keyof T]: T[K] | (Pick<T, K> extends Required<Pick<T, K>> ? never : undefined) };
type DefinedProps<T> = {
  [K in keyof T as undefined extends T[K] ? never : K]: T[K];
} & {
  [K in keyof T as undefined extends T[K] ? K : never]?: Exclude<T[K], undefined>;
};
function hasDefinedValues<T extends object>(props: T): props is T & DefinedProps<T> {
  return Reflect.ownKeys(props).every((key) => Reflect.get(props, key) !== undefined);
}
export function definedProps<T extends object>(props: T): DefinedProps<T> {
  const result = { ...props };
  for (const key of Reflect.ownKeys(result)) {
    if (Reflect.get(result, key) === undefined) {
      Reflect.deleteProperty(result, key);
    }
  }
  if (hasDefinedValues(result)) {
    return result;
  }
  throw new TypeError('Could not normalize UI properties.');
}

import { cva } from 'class-variance-authority';
import { type ClassValue, clsx } from 'clsx';
import type React from 'react';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function wrapStringChild(
  child: React.ReactNode,
  Wrapper: React.ComponentType<{
    children: React.ReactNode;
    className?: string | undefined;
  }>,
  className?: string
): React.ReactNode {
  if (typeof child === 'string') {
    return <Wrapper className={className}>{child}</Wrapper>;
  }
  return child;
}

export interface SharedProps {
  testId?: string | undefined;
}

export interface PortalRootProps {
  defaultOpen?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  open?: boolean | undefined;
}

export type ModalRootProps = PortalRootProps & {
  modal?: boolean | undefined;
};

export interface FocusScopeContentProps {
  onCloseAutoFocus?: ((event: Event) => void) | undefined;
  onOpenAutoFocus?: ((event: Event) => void) | undefined;
}

export type PortalContentProps = FocusScopeContentProps & {
  container?: HTMLElement | undefined;
};

export type FixedPositionContentProps = PortalContentProps & {
  showOverlay?: boolean;
};

export type SemanticVariant = 'success' | 'info' | 'warning' | 'error' | 'disabled';
export type DotSize = 'xxs' | 'xs' | 'sm' | 'md' | 'lg';
export interface StackableProps {
  stacked?: boolean;
}

export const dotColorVariants = cva('', {
  defaultVariants: {
    variant: 'info',
  },
  variants: {
    variant: {
      disabled: 'bg-muted',
      error: 'bg-destructive',
      info: 'bg-primary',
      success: 'bg-primary',
      warning: 'bg-primary',
    },
  },
});

export const dotStackedVariants = cva('!border-background', {
  defaultVariants: {
    size: 'md',
  },
  variants: {
    size: {
      lg: 'border-2',
      md: 'border-2',
      sm: 'border',
      xs: 'border-2',
      xxs: 'border',
    },
  },
});
